import java.io.*;
import java.util.*;

public class Main {
    // Face indices
    // 0=U, 1=D, 2=L, 3=R, 4=F, 5=B

    static final int U = 0, D = 1, L = 2, R = 3, F = 4, B = 5;

    static class Cube {
        char[] f = new char[6];
        Cube(char[] a) {
            System.arraycopy(a, 0, f, 0, 6);
        }
    }

    static class Orientation {
        int[] map = new int[6]; // newFace -> oldFace
        Orientation(int[] m) {
            System.arraycopy(m, 0, map, 0, 6);
        }
    }

    static List<Orientation> orientations = new ArrayList<>();

    static char[] rotateX(char[] a) {
        char[] b = new char[6];
        b[U] = a[B];
        b[F] = a[U];
        b[D] = a[F];
        b[B] = a[D];
        b[L] = a[L];
        b[R] = a[R];
        return b;
    }

    static char[] rotateY(char[] a) {
        char[] b = new char[6];
        b[F] = a[L];
        b[R] = a[F];
        b[B] = a[R];
        b[L] = a[B];
        b[U] = a[U];
        b[D] = a[D];
        return b;
    }

    static char[] rotateZ(char[] a) {
        char[] b = new char[6];
        b[U] = a[L];
        b[R] = a[U];
        b[D] = a[R];
        b[L] = a[D];
        b[F] = a[F];
        b[B] = a[B];
        return b;
    }

    static void generateOrientations() {
        Set<String> seen = new HashSet<>();
        Queue<int[]> q = new ArrayDeque<>();
        int[] id = {0,1,2,3,4,5};
        q.add(id);
        seen.add(Arrays.toString(id));
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            orientations.add(new Orientation(cur));

            int[][] nexts = {
                    rotMapX(cur),
                    rotMapY(cur),
                    rotMapZ(cur)
            };
            for (int[] nx : nexts) {
                String s = Arrays.toString(nx);
                if (seen.add(s)) q.add(nx);
            }
        }
    }

    static int[] rotMapX(int[] a) {
        int[] b = new int[6];
        b[U] = a[B];
        b[F] = a[U];
        b[D] = a[F];
        b[B] = a[D];
        b[L] = a[L];
        b[R] = a[R];
        return b;
    }

    static int[] rotMapY(int[] a) {
        int[] b = new int[6];
        b[F] = a[L];
        b[R] = a[F];
        b[B] = a[R];
        b[L] = a[B];
        b[U] = a[U];
        b[D] = a[D];
        return b;
    }

    static int[] rotMapZ(int[] a) {
        int[] b = new int[6];
        b[U] = a[L];
        b[R] = a[U];
        b[D] = a[R];
        b[L] = a[D];
        b[F] = a[F];
        b[B] = a[B];
        return b;
    }

    static char apply(Cube c, Orientation o, int face) {
        return c.f[o.map[face]];
    }

    static class Placement {
        int outX, outY, outZ; // which outer faces this corner touches: 0/1 or -1 if internal
        Placement(int x, int y, int z) {
            outX = x; outY = y; outZ = z;
        }
    }

    static Placement[] positions = new Placement[8];
    static int[] perm = new int[8];
    static boolean[] usedCube = new boolean[8];
    static int[] chosenOri = new int[8];

    static char[] colorX = new char[2]; // x=0(left),1(right)
    static char[] colorY = new char[2]; // y=0(bottom),1(top)
    static char[] colorZ = new char[2]; // z=0(back),1(front)

    static boolean[] colorUsed = new boolean[256];

    static Cube[] cubes;

    static boolean isBlack(char c) {
        return c == 'K' || c == 'k' || c == 'B' || c == 'b';
    }

    static boolean dfs(int idx) {
        if (idx == 8) return true;

        Placement p = positions[idx];

        for (int ci = 0; ci < 8; ci++) {
            if (usedCube[ci]) continue;
            usedCube[ci] = true;

            for (int oi = 0; oi < orientations.size(); oi++) {
                Orientation o = orientations.get(oi);
                boolean ok = true;
                List<Integer> newly = new ArrayList<>();

                // Internal faces must be black.
                // x internal? impossible here since every corner touches an outer face on each axis.
                // For a 2x2x2 cube, each small cube is at a corner, so exactly 3 outer faces and 3 inner faces.
                char in1 = apply(cubes[ci], o, p.outX == 0 ? R : L);
                char in2 = apply(cubes[ci], o, p.outY == 0 ? U : D);
                char in3 = apply(cubes[ci], o, p.outZ == 0 ? F : B);
                if (!isBlack(in1) || !isBlack(in2) || !isBlack(in3)) {
                    continue;
                }

                // Outer faces colors must match per big face and all 6 big faces distinct.
                int[] dirs = new int[3];
                char[] cols = new char[3];

                dirs[0] = p.outX == 0 ? L : R;
                cols[0] = apply(cubes[ci], o, dirs[0]);

                dirs[1] = p.outY == 0 ? D : U;
                cols[1] = apply(cubes[ci], o, dirs[1]);

                dirs[2] = p.outZ == 0 ? B : F;
                cols[2] = apply(cubes[ci], o, dirs[2]);

                for (char c : cols) {
                    if (isBlack(c)) { ok = false; break; }
                }
                if (!ok) continue;

                // assign/check x face
                char c;
                if (p.outX == 0) {
                    c = cols[0];
                    if (colorX[0] == 0) {
                        if (colorUsed[c]) ok = false;
                        else { colorX[0] = c; colorUsed[c] = true; newly.add((int)c); }
                    } else if (colorX[0] != c) ok = false;
                } else {
                    c = cols[0];
                    if (colorX[1] == 0) {
                        if (colorUsed[c]) ok = false;
                        else { colorX[1] = c; colorUsed[c] = true; newly.add((int)c); }
                    } else if (colorX[1] != c) ok = false;
                }

                if (ok) {
                    if (p.outY == 0) {
                        c = cols[1];
                        if (colorY[0] == 0) {
                            if (colorUsed[c]) ok = false;
                            else { colorY[0] = c; colorUsed[c] = true; newly.add((int)c); }
                        } else if (colorY[0] != c) ok = false;
                    } else {
                        c = cols[1];
                        if (colorY[1] == 0) {
                            if (colorUsed[c]) ok = false;
                            else { colorY[1] = c; colorUsed[c] = true; newly.add((int)c); }
                        } else if (colorY[1] != c) ok = false;
                    }
                }

                if (ok) {
                    if (p.outZ == 0) {
                        c = cols[2];
                        if (colorZ[0] == 0) {
                            if (colorUsed[c]) ok = false;
                            else { colorZ[0] = c; colorUsed[c] = true; newly.add((int)c); }
                        } else if (colorZ[0] != c) ok = false;
                    } else {
                        c = cols[2];
                        if (colorZ[1] == 0) {
                            if (colorUsed[c]) ok = false;
                            else { colorZ[1] = c; colorUsed[c] = true; newly.add((int)c); }
                        } else if (colorZ[1] != c) ok = false;
                    }
                }

                if (ok) {
                    perm[idx] = ci;
                    chosenOri[idx] = oi;
                    if (dfs(idx + 1)) return true;
                }

                // rollback
                for (int ch : newly) colorUsed[ch] = false;
                if (!newly.isEmpty()) {
                    if (p.outX == 0 && newly.contains((int)colorX[0])) colorX[0] = 0;
                    if (p.outX == 1 && newly.contains((int)colorX[1])) colorX[1] = 0;
                    if (p.outY == 0 && newly.contains((int)colorY[0])) colorY[0] = 0;
                    if (p.outY == 1 && newly.contains((int)colorY[1])) colorY[1] = 0;
                    if (p.outZ == 0 && newly.contains((int)colorZ[0])) colorZ[0] = 0;
                    if (p.outZ == 1 && newly.contains((int)colorZ[1])) colorZ[1] = 0;
                }
            }

            usedCube[ci] = false;
        }

        return false;
    }

    public static void main(String[] args) throws Exception {
        generateOrientations();

        FastScanner fs = new FastScanner(System.in);
        List<String> tokens = new ArrayList<>();
        while (true) {
            String s = fs.next();
            if (s == null) break;
            tokens.add(s);
        }

        if (tokens.isEmpty()) return;

        // We assume input gives 8 cubes, each by 6 symbols/chars.
        // Since original statement about sheet/net formatting is omitted here,
        // this solver expects 48 color tokens or 8 strings of length 6, etc.
        // Each token contributes characters.
        List<Character> chars = new ArrayList<>();
        for (String t : tokens) {
            if (t.length() == 1) chars.add(t.charAt(0));
            else {
                for (int i = 0; i < t.length(); i++) chars.add(t.charAt(i));
            }
        }

        if (chars.size() < 48) {
            System.out.println("No");
            return;
        }

        cubes = new Cube[8];
        int ptr = 0;
        for (int i = 0; i < 8; i++) {
            char[] a = new char[6];
            for (int j = 0; j < 6; j++) a[j] = chars.get(ptr++);
            cubes[i] = new Cube(a);
        }

        // 8 corner positions of the 2x2x2 cube
        int idx = 0;
        for (int x = 0; x <= 1; x++) {
            for (int y = 0; y <= 1; y++) {
                for (int z = 0; z <= 1; z++) {
                    positions[idx++] = new Placement(x, y, z);
                }
            }
        }

        boolean ans = dfs(0);
        System.out.println(ans ? "Yes" : "No");
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (Character.isWhitespace(c));
            while (c != -1 && !Character.isWhitespace(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}

